// Some portions generated by Claude
package org.eclipse.rdf4j.sail.inferencer.fc;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;

import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;

import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.model.vocabulary.RDF;
import org.eclipse.rdf4j.model.vocabulary.RDFS;
import org.eclipse.rdf4j.sail.SailException;
import org.eclipse.rdf4j.sail.memory.MemoryStore;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.Timeout;

/**
 * Shutting down the inferencer force-closes the backing connection of every open inferencer connection. Closing such a
 * connection afterwards must not reopen (and thereby re-initialize) the backing store to repair the shared schema
 * cache; the repair has to wait until the store is used again.
 */
class SchemaCachingRDFSInferencerShutDownCloseTest {

	@Test
	@Timeout(value = 15, unit = TimeUnit.SECONDS)
	void closingDirtyConnectionAfterShutDownDoesNotReopenTheBackingStore() {
		AtomicInteger initializations = new AtomicInteger();
		MemoryStore base = new MemoryStore() {
			@Override
			protected void initializeInternal() throws SailException {
				initializations.incrementAndGet();
				super.initializeInternal();
			}
		};
		base.setConnectionTimeOut(10);
		SchemaCachingRDFSInferencer inferencer = new SchemaCachingRDFSInferencer(base);
		inferencer.init();
		var vf = SimpleValueFactory.getInstance();
		IRI subclass = vf.createIRI("urn:shutdown-close:subclass");
		IRI superclass = vf.createIRI("urn:shutdown-close:superclass");
		IRI instance = vf.createIRI("urn:shutdown-close:instance");

		SchemaCachingRDFSInferencerConnection connection = inferencer.getConnection();
		connection.begin();
		connection.addStatement(subclass, RDFS.SUBCLASSOF, superclass);
		inferencer.shutDown();
		connection.close();

		assertEquals(1, initializations.get(),
				"closing a connection after shut down must not re-initialize the backing store");

		inferencer.init();
		try (SchemaCachingRDFSInferencerConnection next = inferencer.getConnection()) {
			next.begin();
			next.addStatement(instance, RDF.TYPE, subclass);
			next.commit();
			assertFalse(next.hasStatement(instance, RDF.TYPE, superclass, true),
					"the rolled-back subclass relation must not survive in the shared schema cache");
		} finally {
			inferencer.shutDown();
		}
	}
}
